function calculate(s: string): number {
  let result = 0; // сумма уже разобранных слагаемых на текущем уровне скобок
  let sign = 1; // знак перед следующим числом или скобкой: +1 или -1
  let num = 0; // число, которое сейчас читаем по цифрам
  // При входе в скобку сохраняем состояние внешнего уровня: [result, sign]
  const stack: number[] = [];

  for (let i = 0; i < s.length; i++) {
    const c = s[i];

    if (c >= '0' && c <= '9') {
      // Число может состоять из нескольких цифр
      num = num * 10 + (c.charCodeAt(0) - 48);
    } else if (c === '+' || c === '-') {
      // Число закончилось — добавляем его с его знаком
      result += sign * num;
      num = 0;
      // Знак для следующего слагаемого (унарный минус работает так же: result = 0)
      sign = c === '+' ? 1 : -1;
    } else if (c === '(') {
      // Запоминаем внешний результат и знак перед скобкой,
      // а внутри скобки начинаем считать с нуля
      stack.push(result, sign);
      result = 0;
      sign = 1;
    } else if (c === ')') {
      // Завершаем последнее число внутри скобки
      result += sign * num;
      num = 0;
      // Значение скобки умножаем на знак перед ней и прибавляем к внешнему результату
      const signBefore = stack.pop()!;
      const outer = stack.pop()!;
      result = outer + signBefore * result;
    }
    // Пробелы просто пропускаем
  }

  // Последнее число в строке
  return result + sign * num;
}

// Время: O(n) — один проход по строке
// Память: O(n) — стек при глубокой вложенности скобок
